/**
 * Wait for the scan's background writes to land.
 *
 * `POST /api/scan?wait=true` resolves when the WALK finishes: diskScanner marks
 * the scan complete and then fires the snapshot write off unawaited, which is
 * the right call for the product — a durability step must not hold up an answer
 * that is already correct. But /api/agent/summary reads that store for its
 * forecast, so `snapshotCount` and the sentence built from it are LIVE state,
 * exactly like `forecast.freeBytes` further down. Two reads taken either side
 * of the write legitimately disagree: Windows CI caught 0 then 1.
 *
 * `settled()` is the ledger those writes register with, so this is an answer
 * rather than a guess — no polling, no timeout, and if it ever hangs `pending()`
 * names the write still running instead of leaving a bare timeout to debug.
 *
 * Settling BEFORE the first read is what keeps the equality assertion at full
 * strength: every field compared, nothing exempted to buy a green.
 */
async function settleBackgroundWrites(): Promise<void> {
  let timer: NodeJS.Timeout | undefined;
  const giveUp = new Promise<never>((_, reject) => {
    timer = setTimeout(
      () => reject(new Error(`background writes never settled; still running: ${pending().join(', ') || '(none)'}`)),
      20_000,
    );
  });
  try {
    await Promise.race([settled(), giveUp]);
  } finally {
    clearTimeout(timer);
  }
}

test('agent summary: raw+formatted bytes, stable ids, deterministic order, real forecast', async () => {
  const { port, close } = await listen();
  try {
    const scan = await req(port, 'POST', '/api/scan?wait=true&waitMs=30000', { path: fixture });
    const scanId = scan.body.scanId as string;

    // Both reads must see a settled store — see settleBackgroundWrites above.
    await settleBackgroundWrites();

    const r = await req(port, 'GET', `/api/agent/summary?scanId=${scanId}`);
    assert.equal(r.status, 200, JSON.stringify(r.body));
    const s = r.body;

    assert.equal(s.scanId, scanId);
    assert.equal(s.rootPath, fixture);
    assert.equal(typeof s.totals.bytes, 'number');
    assert.equal(s.totals.formatted, formatBytes(s.totals.bytes), 'raw and formatted agree');
    assert.equal(s.totals.fileCount, 5);

    assert.equal(s.largestFiles[0].name, 'huge.bin', 'largest first');
    assert.equal(s.largestFiles[0].size, 2 * 1024 * 1024);
    assert.equal(s.largestFiles[0].sizeFormatted, '2.0 MB');
    const fileSizes = s.largestFiles.map((f: { size: number }) => f.size);
    assert.deepEqual(fileSizes, [...fileSizes].sort((a, b) => b - a), 'files size-desc');

    const folderSizes = s.largestFolders.map((f: { size: number }) => f.size);
    assert.deepEqual(folderSizes, [...folderSizes].sort((a, b) => b - a), 'folders size-desc');

    const nm = s.cleanup.groups.find((g: { id: string }) => g.id === 'regen-node-modules');
    assert.ok(nm, 'stable rule id present');
    assert.equal(nm.regenerateCmd, 'npm install');
    assert.equal(nm.totalSizeFormatted, formatBytes(nm.totalSize));
    const junk = s.cleanup.byCategory.find((c: { category: string }) => c.category === 'junk');
    assert.ok(junk && junk.bytes > 0, '.DS_Store lands in the junk category');
    assert.equal(s.cleanup.reclaimableFormatted, formatBytes(s.cleanup.reclaimableBytes));

    assert.ok(['ok', 'insufficient', 'stable', 'shrinking', 'erratic'].includes(s.forecast.status));
    assert.equal(typeof s.forecast.bytesPerDayFormatted, 'string');

    // Deterministic: an immediate second read is identical.
    //
    // Everything derived from the scan must match exactly. `forecast.freeBytes`
    // is deliberately excluded, and this is not a loophole: it is a live
    // reading of the volume's free space, taken fresh on each request. The disk
    // genuinely changes between two calls — this assertion failed in CI with an
    // 28 KB difference — so demanding it be identical asserts something that is
    // not true of the system, which is how a flaky test is born. It is checked
    // for presence and plausibility instead.
    const again = await req(port, 'GET', `/api/agent/summary?scanId=${scanId}`);
    const strip = (body: unknown): unknown => {
      const clone = JSON.parse(JSON.stringify(body)) as { forecast: { freeBytes?: number; freeFormatted?: string } };
      delete clone.forecast.freeBytes;
      delete clone.forecast.freeFormatted;
      return clone;
    };
    assert.deepEqual(strip(again.body), strip(s), 'two reads over the same scan are identical');

    const free = (again.body as { forecast: { freeBytes: number } }).forecast.freeBytes;
    assert.ok(Number.isFinite(free) && free > 0, 'free space is still reported, and is a real number');
  } finally {
    await close();
  }
});

test('agent summary answers 202 while the scan is still running and 404 for unknown scans', async () => {
  const { port, close } = await listen();
  try {
    const big = path.join(__dirname, '..', 'node_modules');
    const started = await req(port, 'POST', '/api/scan', { path: big });
    const r = await req(port, 'GET', `/api/agent/summary?scanId=${started.body.scanId}`);
    assert.equal(r.status, 202);
    assert.equal(r.body.status, 'running');

    const missing = await req(port, 'GET', '/api/agent/summary?scanId=nope');
    assert.equal(missing.status, 404);
    assert.equal(missing.body.code, 'SCAN_NOT_FOUND');
  } finally {
    // The node_modules scan is still walking: stopped here, or it would save
    // its snapshot into the data folder after the file had removed it.
    cancelAllScans();
    await close();
    fs.rmSync(fixture, { recursive: true, force: true });
    fs.rmSync(process.env.TREEMAP_DATA_DIR!, { recursive: true, force: true });
  }
});

declare const require: (name: string) => any;

const assert = require("assert/strict");
const test = require("node:test");
import { defaultTerminalCommands } from "../src/extensions/defaultTerminalCommands";
import { buildCustomCommandArguments } from "../src/extensions/customCommandBuilder";
import { escapeTemplateValue, quoteForShell, validateTerminalValue } from "../src/extensions/shell";

test("escapeTemplateValue on Windows does not add extra quotes and doubles internal quotes", () => {
    const input = 'C:\\path\\to\\My "Quoted" Solution.sln';
    const escaped = escapeTemplateValue(input, "win32");

    assert.equal(escaped, 'C:\\path\\to\\My ""Quoted"" Solution.sln');
});

test("escapeTemplateValue on Linux escapes shell-sensitive characters in quoted templates", () => {
    const input = "line\\path\"$`\nnext\u0000";
    const escaped = escapeTemplateValue(input, "linux");

    assert.equal(escaped, "line\\\\path\\\"\\$\\`next");
});

test("escapeTemplateValue on macOS escapes shell-sensitive characters in quoted templates", () => {
    const input = "folder\\name\"$`\r\nvalue\u0000";
    const escaped = escapeTemplateValue(input, "darwin");

    assert.equal(escaped, "folder\\\\name\\\"\\$\\`value");
});

test("quoteForShell on Windows wraps with quotes and escapes internal quotes", () => {
    const input = 'C:\\temp\\a "b".sln';
    const quoted = quoteForShell(input, "win32");

    assert.equal(quoted, '"C:\\temp\\a ""b"".sln"');
});

test("quoteForShell on Linux uses single-quote escaping", () => {
    const input = "/tmp/it's-here";
    const quoted = quoteForShell(input, "linux");

    assert.equal(quoted, "'/tmp/it'\\''s-here'");
});

test("quoteForShell on macOS uses single-quote escaping", () => {
    const input = "/Users/test/O'Brien";
    const quoted = quoteForShell(input, "darwin");

    assert.equal(quoted, "'/Users/test/O'\\''Brien'");
});

test("validateTerminalValue accepts normal path and argument values", () => {
    assert.doesNotThrow(() => validateTerminalValue("C:\\path\\ok.sln", "path"));
    assert.doesNotThrow(() => validateTerminalValue("--project", "argument"));
});

test("validateTerminalValue rejects control character injection", () => {
    assert.throws(() => validateTerminalValue("abc\nxyz", "argument"), /Unsafe terminal argument/);
    assert.throws(() => validateTerminalValue("abc\rxyz", "path"), /Unsafe terminal path/);
    assert.throws(() => validateTerminalValue("abc\u0000xyz", "path"), /Unsafe terminal path/);
});

test("clean custom command generation is compatible on Windows", () => {
    const args = buildCustomCommandArguments(
        defaultTerminalCommands.clean,
        { projectPath: 'C:\\repo\\My "Great" App\\MySolution.sln' },
        "win32"
    );

    assert.deepEqual(args, [
        "dotnet",
        "clean",
        '"C:\\repo\\My ""Great"" App\\MySolution.sln"'
    ]);
});

test("clean custom command generation is compatible on Linux", () => {
    const args = buildCustomCommandArguments(
        defaultTerminalCommands.clean,
        { projectPath: '/repo/My "Great" App/MySolution.sln' },
        "linux"
    );

    assert.deepEqual(args, [
        "dotnet",
        "clean",
        '"/repo/My \\\"Great\\\" App/MySolution.sln"'
    ]);
});

test("clean custom command generation is compatible on macOS", () => {
    const args = buildCustomCommandArguments(
        defaultTerminalCommands.clean,
        { projectPath: '/Users/me/My "Great" App/MySolution.sln' },
        "darwin"
    );

    assert.deepEqual(args, [
        "dotnet",
        "clean",
        '"/Users/me/My \\\"Great\\\" App/MySolution.sln"'
    ]);
});

test("clean custom command generation strips control characters from path value", () => {
    const args = buildCustomCommandArguments(
        defaultTerminalCommands.clean,
        { projectPath: '/repo/MySolution.sln\nrm -rf /\u0000' },
        "linux"
    );

    assert.equal(args[2], '"/repo/MySolution.slnrm -rf /"');
});
